<div class="page-title"><div><p class="eyebrow">Competition</p><h1>Results and Winners</h1></div></div>
<form class="card filters" method="get" action="<?= e(url('/admin/results')) ?>"><select name="quiz" aria-label="Quiz"><option value="">Select a quiz…</option><?php foreach ($quizzes as $z): ?><option value="<?= (int)$z['id'] ?>" <?= $qid === (int)$z['id'] ? 'selected' : '' ?>><?= e($z['title']) ?> (<?= (int)$z['n'] ?> attempts)</option><?php endforeach; ?></select><button class="btn btn-sm" type="submit">Show leaderboard</button></form>
<?php if (!$qid): ?><div class="card empty">Select a quiz to preview its leaderboard and eligibility.</div><?php else: $quiz = $lb['quiz']; ?>
<?php if ($live): ?><div class="alert a-warn"><?= (int)$live ?> participant(s) are still taking this quiz. Their attempts are not included yet.</div><?php endif; ?>
<?php if ($pending): ?><div class="alert a-warn"><?= (int)$pending ?> attempt(s) are Pending Review and excluded. <a href="<?= e(url('/admin/verification')) ?>">Open verification</a></div><?php endif; ?>
<section class="card"><h2>Ranking rules in force</h2><ul class="plain"><li>Best valid attempt per participant, within the attempt limit (<?= (int)$quiz['max_attempts'] ?> + authorised extras).</li><li>Integrity policy: <?= e($quiz['visibility_policy']) ?> after <?= (int)$quiz['visibility_threshold'] ?> page-leave(s). Pending Review, Disqualified and Incomplete attempts are excluded.</li><li>Timed-out attempts: <?= $quiz['timeout_counts'] ? 'ranked on saved answers' : 'excluded' ?>. Tie-breaker: <?= $quiz['tiebreak'] === 'time' ? 'faster completion time; unresolved ties share a rank' : 'none (equal scores share a rank)' ?>.</li></ul></section>
<?php if ($lb['ranked']): $top = array_values(array_filter($lb['ranked'], fn($r) => (int)$r['rank'] <= 3)); $first = array_values(array_filter($top, fn($r) => (int)$r['rank'] === 1)); $second = array_values(array_filter($top, fn($r) => (int)$r['rank'] === 2)); $third = array_values(array_filter($top, fn($r) => (int)$r['rank'] === 3));
  $pod = fn($list, $cls, $m) => $list ? implode('', array_map(fn($r) => '<div class="pod ' . $cls . '"><div class="medal">' . $m . '</div>' . avatar_html(['id' => $r['user_id'], 'full_name' => $r['full_name'], 'has_avatar' => $r['has_avatar']], 56) . '<h3>' . e($r['full_name']) . '</h3><div class="pts">' . e(num($r['final_marks'])) . '/' . (int)$r['max_marks'] . '</div><small>' . e(num($r['percentage'])) . '% · ' . e(fmt_duration((int)$r['duration_seconds'])) . '</small></div>', $list)) : ''; ?>
<section aria-label="Podium"><div class="podium"><?= $pod($second, 'g2', '🥈') ?><?= $pod($first, 'g1', '🥇') ?><?= $pod($third, 'g3', '🥉') ?></div></section><?php endif; ?>
<section class="card"><h2 style="margin-top:0">Leaderboard preview (<?= count($lb['ranked']) ?> ranked)</h2>
<?php if (!$lb['ranked']): ?><p class="empty">No eligible attempts yet.</p><?php else: ?>
<div class="filters"><input type="search" id="lbq" data-filter="#lb" placeholder="Search participant" aria-label="Search leaderboard"></div>
<div class="table-wrap" id="lb"><table class="cards-sm"><thead><tr><th>Rank</th><th>Participant</th><th>Score</th><th>%</th><th>Time</th><th></th></tr></thead><tbody>
<?php foreach ($lb['ranked'] as $r): $b = badge_for_rank((int)$r['rank'], 3); ?><tr data-s="<?= e(mb_strtolower($r['full_name'])) ?>"><td data-l="Rank"><?= e(medal($b)) ?> <?= (int)$r['rank'] ?></td><td data-l="Participant"><span class="person"><?= avatar_html(['id' => $r['user_id'], 'full_name' => $r['full_name'], 'has_avatar' => $r['has_avatar']], 32) ?><?= e($r['full_name']) ?></span></td><td data-l="Score"><?= e(num($r['final_marks'])) ?>/<?= (int)$r['max_marks'] ?></td><td data-l="%"><?= e(num($r['percentage'])) ?>%</td><td data-l="Time"><?= e(fmt_duration((int)$r['duration_seconds'])) ?></td><td><a href="<?= e(url('/admin/submissions/' . $r['id'])) ?>">Inspect</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="card"><h2 style="margin-top:0">Excluded attempts (<?= count($lb['excluded']) ?>) — review queue and reasons</h2>
<?php if (!$lb['excluded']): ?><p class="empty">None.</p><?php else: ?>
<div class="filters"><input type="search" id="exq" data-filter="#ex" data-filter-select="#exg" placeholder="Search participant" aria-label="Search excluded attempts"><select id="exg" aria-label="Eligibility"><option value="">All eligibility</option><?php foreach (ELIG_LABELS as $k => $l): ?><option value="<?= $k ?>"><?= e($l) ?></option><?php endforeach; ?></select></div>
<ul class="plain" id="ex"><?php foreach ($lb['excluded'] as $r): ?><li data-s="<?= e(mb_strtolower($r['full_name'])) ?>" data-g="<?= e($r['eligibility']) ?>"><span><a href="<?= e(url('/admin/submissions/' . $r['id'])) ?>"><?= e($r['full_name']) ?> (attempt <?= (int)$r['attempt_no'] ?>)</a> <?= badge($r['eligibility']) ?></span><small><?= e($r['note']) ?></small></li><?php endforeach; ?></ul><?php endif; ?></section>
<?php if ($canFinalize && $lb['ranked']): ?>
<form class="card" method="post" action="<?= e(url('/admin/results/finalize')) ?>" data-confirm="Save these results as the official snapshot? Earlier official versions stay on record as superseded."><h2><?= $history ? 'Publish a corrected version' : 'Finalise results' ?></h2><?= csrf_field() ?><input type="hidden" name="quiz_id" value="<?= $qid ?>">
  <label for="prizes">Number of prizes (gold/silver/bronze badges for 3)</label><input id="prizes" name="prizes" type="number" min="0" max="10" value="3">
  <?php if ($history): ?><label for="reason">Correction reason (required for a new version)</label><input id="reason" name="reason" required minlength="5"><?php endif; ?>
  <?php if ($pending): ?><label class="check"><input type="checkbox" name="ack_pending" value="1"> <span>I understand <?= (int)$pending ?> pending attempt(s) are excluded from this snapshot.</span></label><?php endif; ?>
  <label class="check"><input type="checkbox" name="publish" value="1" checked> <span>Publish to participants and notify them</span></label>
  <button class="btn" type="submit">Finalise and save snapshot</button></form>
<?php endif; ?>
<section class="card"><h2>Official result versions</h2><?php if (!$history): ?><p class="empty">Not finalised yet.</p><?php endif; ?><ul class="plain"><?php foreach ($history as $h): ?><li><a href="<?= e(url('/admin/results/view/' . $h['id'])) ?>">Version <?= (int)$h['result_version'] ?></a> <?= badge($h['status']) ?> <small><?= e(fmt_dt($h['finalized_at'])) ?> by <?= e($h['finalized_by_name']) ?><?= $h['correction_reason'] ? ' · ' . e($h['correction_reason']) : '' ?></small></li><?php endforeach; ?></ul></section>
<?php endif; ?>
